const answerDefaults=()=>({reading:{},listening:{},mock:null,speakingNotes:'',history:[],timers:{},speakingEntryIds:{}});
const answerSnapshot=()=>Object.fromEntries(Object.keys(answerDefaults()).map(key=>[key,state[key]??answerDefaults()[key]]));
function persistAnswerState(){try{localStorage.setItem(KEY+':answers:'+(answerOwner||'guest'),JSON.stringify(answerSnapshot()));}catch{}}
function paintAnswerStatus(){if(isTeacherSite())return;const message=answerSync?.status()||'Your answers save automatically.';document.querySelectorAll('.local-status,[data-answer-save-status]').forEach(node=>{if(node.textContent!==message)node.textContent=message;});}
function syncAnswerOwner(){
 const next=studentId()||'guest';if(answerOwner===next)return;
 if(answerOwner!==null)persistAnswerState();
 const keepLegacy=answerOwner===null&&legacyAnswerOwner===next;answerOwner=next;
 let saved;try{saved=JSON.parse(localStorage.getItem(KEY+':answers:'+next)||'null');}catch{}
 Object.assign(state,saved|| (keepLegacy?answerSnapshot():answerDefaults()));state.answerOwner=next;
 answerSync?.connectionChanged();
 if(next!=='guest'&&answerSync)for(const field of ['reading','listening','speaking','mock']){
  const value=field==='speaking'?{notes:state.speakingNotes}:state[field],initial=value&&JSON.stringify(value)!=='{}'&&JSON.stringify(value)!=='{"notes":""}'?value:undefined;
  const apply=value=>{if(answerOwner!==next||studentId()!==next)return;if(field==='speaking')state.speakingNotes=value?.notes||'';else state[field]=value??(field==='mock'?null:{});persistAnswerState();render();};
  const restored=answerSync.open('practice:'+field,initial,apply);if(restored!==undefined){if(field==='speaking')state.speakingNotes=restored?.notes||'';else state[field]=restored;}
 }
 persistAnswerState();paintAnswerStatus();
}

// Only restore explicitly scoped writing; a shared browser may retain another account's old aggregate state.
try{const own=JSON.parse(localStorage.getItem(KEY+':writing:'+writingOwner)||'{}');state.drafts=own.drafts||{};state.writeResults=own.writeResults||{};}catch{state.drafts={};state.writeResults={};}
function syncWritingOwner(){const next=studentId()||'guest';if(next===writingOwner)return;try{localStorage.setItem(KEY+':writing:'+writingOwner,JSON.stringify({drafts:state.drafts,writeResults:state.writeResults}));}catch{}writingOwner=next;state.drafts={};state.writeResults={};for(const key of Object.keys(state.timers))if(key.startsWith('write-'))delete state.timers[key];try{const own=JSON.parse(localStorage.getItem(KEY+':writing:'+next)||'{}');state.drafts=own.drafts||{};state.writeResults=own.writeResults||{};}catch{}}
function save(){syncAnswerOwner();persistAnswerState();if(answerSync&&!isTeacherSite()&&answerOwner===studentId()){for(const field of ['reading','listening','speaking','mock'])answerSync.capture('practice:'+field,field==='speaking'?{notes:state.speakingNotes}:state[field]);}try{localStorage.setItem(KEY+':writing:'+writingOwner,JSON.stringify({drafts:state.drafts,writeResults:state.writeResults}));localStorage.setItem(KEY,JSON.stringify(state));}catch{storageOk=false;$('.local-status').innerHTML='Storage unavailable';}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function updateProfile(){ $('#profileBtn').textContent=state.name?state.name[0].toUpperCase():'A';$('#profileBtn').title=state.name||'Set learner name'; }
updateProfile();
$('#profileBtn').onclick=()=>{if(isTeacherSite()){location.hash='teacher/settings';return;}$('#learnerName').value=state.name;$('#profileDialog').showModal();};
$('#logoutBtn').addEventListener('click',async()=>{try{await logoutClassroom();}catch(error){toast(error.message);}});
$('#closeProfile').onclick=()=>$('#profileDialog').close();
$('#profileForm').onsubmit=e=>{e.preventDefault();state.name=studentName()||$('#learnerName').value.trim();save();updateProfile();$('#profileDialog').close();render();};
