function officialLink(href,label,classes='button secondary'){return `<a class="${classes}" href="${esc(href)}" target="_blank" rel="noopener noreferrer">${esc(label)} <span aria-hidden="true">↗</span><span class="sr-only"> (opens official source in a new tab)</span></a>`;}
