function timerText(key){const t=state.timers[key];if(!t)return '--:--';const seconds=Math.max(0,Math.ceil((t.end-Date.now())/1000));return `${Math.floor(seconds/60).toString().padStart(2,'0')}:${(seconds%60).toString().padStart(2,'0')}`;}
const timerSpan=(key,defaultText)=>`<span class="timer" data-timer="${key}" aria-label="Time remaining">${state.timers[key]?timerText(key):defaultText}</span>`;
function startTimer(key,minutes){state.timers[key]={end:Date.now()+minutes*60000};save();render();}
function downloadText(filename,text){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function historyAdd(entry){const completed={id:crypto.randomUUID(),date:Date.now(),name:studentName()||state.name||'Learner',mockId:entry.context==='mock'?String(state.mock?.started||''):null,...entry};state.history.unshift(completed);state.history=state.history.slice(0,100);save();queueSubmission(completed);return completed;}
function report(entry){let text=`RICHMOUNT IELTS STUDIO\nLearner: ${entry.name}\nActivity: ${entry.title}\nDate: ${date(entry.date)}\nOriginal practice — not an official IELTS score\n\n`;
 if(entry.kind==='writing'){text+=`Words: ${entry.result.wordCount}\nCommon errors flagged: ${entry.result.issues.length}\n\nORIGINAL RESPONSE\n${entry.text}\n\nCHECKS\n${entry.result.issues.map(i=>`${i.original}: ${i.message}`).join('\n')}\n\n${entry.result.notes.join('\n')}\n\nRule-based checks may miss errors or change meaning. Review suggestions with your teacher. No Writing band is assigned.`;}
 else if(entry.details){text+=`Score: ${entry.score}/${entry.total}\n\n`+entry.details.map((d,i)=>`${i+1}. ${d.text}\nYour answer: ${d.given||'(blank)'}\nCorrect answer: ${d.answer}\n${d.correct?'Correct':'Incorrect'} — ${d.evidence}`).join('\n\n');}
 else text+=`Self-practice completed. Speaking has not been scored.\nNotes: ${entry.notes||''}`;
 return text;}
